#include <delta/core/protocol.hpp>
#include <delta/core/canonical.hpp>
#include <iostream>
#include <iomanip>
#include <string>
#include <utility>
namespace ca=delta::core::canonical;
namespace pr=delta::core::protocol;
ca::Bytes unhex(const std::string& s){ca::Bytes b;
 for(std::size_t i=0;i<s.size();i+=2)
  b.push_back(static_cast<std::byte>(std::stoul(s.substr(i,2),nullptr,16)));
 return b;}
int main(){const std::pair<const char*,const char*> cases[]={
{"original-1",""},
{"original-2",""},
{"original-3",""},
{"original-4",""},
{"original-5",""},
{"original-6",""},
{"original-7",""},
{"original-8",""},
{"original-9",""},
{"field-0-durable_sequence",""},
{"field-1-durable_sequence",""},
{"field-2-durable_sequence",""},
{"field-3-durable_sequence",""},
{"field-4-durable_sequence",""},
{"field-5-height",""},
{"field-6-height",""},
{"field-7-height",""},
{"field-8-height",""},
{"field-9-height",""},
{"field-10-view",""},
{"field-11-view",""},
{"field-12-view",""},
{"field-13-formal_semantics_id",""},
{"field-14-schema_version",""},
{"field-15-type_name",""},
{"field-16-body_hash",""},
{"field-17-signature_id",""},
{"field-18-validator_epoch_id",""},
{"field-19-context_id",""},
{"field-20-kind",""},
{"field-21-round_id",""},
{"field-22-validator_id",""},
{"field-23-context_id",""},
{"field-24-round_id",""},
{"field-25-validator_id",""},
{"field-26-kind",""},
{"missing-field",""},
{"extra-field",""},
{"duplicate-field",""},
{"reordered-field",""},
{"trailing-byte",""},
{"truncated",""},
{"magic",""},
{"major",""},
{"minor",""},
{"type",""},
{"root-tag",""},
{"field-count",""},
{"key-tag",""}
};for(const auto& [name,hex]:cases){const auto raw=unhex(hex);bool accepted=false;
 std::string id;try{const auto v=pr::parse_vote(raw);
 if(pr::encode(v)!=raw)throw std::runtime_error("native canonical mismatch");
 id=ca::content_id(ca::Type::vote,raw);accepted=true;
 }catch(const ca::DecodeError&){}catch(const pr::ProtocolError&){}
 std::cout<<"{\"name\":"<<std::quoted(name)<<",\"accepted\":"<<(accepted?"true":"false")
 <<",\"vote_id\":"<<std::quoted(id)<<"}\n";}}
